// P1, book loans: one Book machine per book id, created by add.
module library

enum Status { unadded, available, lent, retired }

machine Book {
  state {
    status : Status = unadded
    loans  : 0..3   = 0
  }
  terminal status == retired

  action Add()
  action Lend()
  action GiveBack()
  action Retire()

  on Add {
    require status == unadded else reject "exists"
    status' = available
  }
  on Lend {
    require status == available else reject "not-available"
    require loans < 3 else reject "loan-limit"
    status' = lent
    loans' = loans + 1
  }
  on GiveBack {
    require status == lent else reject "not-lent"
    status' = available
  }
  on Retire {
    require status == available else reject "not-available"
    status' = retired
  }

  invariant loans-bounded: loans <= 3
  invariant unadded-never-lent: status == unadded implies loans == 0
}
EOF
cat > host.map.json <<'EOF'
{
  "$schema": "./host.map.schema.json",
  "module": "library",
  "instances": {
    "books": { "machine": "Book", "createdBy": "add", "keyArgument": "book" }
  },
  "methods": {
    "add":      { "instance": "books", "key": "$arg:book", "action": "Add" },
    "lend":     { "instance": "books", "key": "$arg:book", "action": "Lend" },
    "giveBack": { "instance": "books", "key": "$arg:book", "action": "GiveBack" },
    "retire":   { "instance": "books", "key": "$arg:book", "action": "Retire" }
  },
  "queries": {
    "book": { "instance": "books", "key": "$arg:book", "fields": { "status": "status", "loans": "loans" } }
  }
}
EOF
