  const h = await createHost();
  assert.equal(await h.book('a'), null);
  assert.equal((await h.lend('a')).ok, false);
  assert.equal(await h.book('a'), null);
  assert.deepEqual(await h.add('a'), ok);
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 0 });
  assert.equal((await h.giveBack('a')).ok, false);
  assert.deepEqual(await h.lend('a'), ok);
  assert.equal((await h.lend('a')).ok, false);
  assert.equal((await h.retire('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'lent', loans: 1 });
  assert.deepEqual(await h.giveBack('a'), ok);
  for (let i = 0; i < 2; i++) { assert.deepEqual(await h.lend('a'), ok); assert.deepEqual(await h.giveBack('a'), ok); }
  const r = await h.lend('a');
  assert.equal(r.ok, false);
  assert.equal(typeof (r as any).reason, 'string');
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 3 });
  assert.deepEqual(await h.retire('a'), ok);
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 3 });
  for (const c of ['add', 'lend', 'giveBack', 'retire'] as const) assert.equal((await h[c]('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 3 });
  assert.deepEqual(await h.add('b'), ok);
  assert.deepEqual(await h.book('b'), { status: 'available', loans: 0 });
  assert.equal(await h.book('c'), null);
});

